const {chromium}=require('./browser/node_modules/playwright');
(async()=>{const browser=await chromium.launch();const errors=[];for(const [port,domain,expected] of [[4181,'dracula-design.com',5],[4183,'dracula-food.com',0]]){const ctx=await browser.newContext({viewport:{width:1440,height:1000}});const p=await ctx.newPage();p.on('pageerror',e=>errors.push(e.message));p.on('response',r=>{if(r.status()>=500)errors.push(r.status()+' '+r.url())});await p.goto('http://127.0.0.1:'+port+'/ro/account');await p.locator('[name=email]').fill('client@'+domain);await p.locator('[name=password]').fill(process.env.QA_PASSWORD);await p.locator('form button[type=submit]').click();await p.waitForSelector('[data-action=logout]');console.log(domain,'CLIENT LOGIN OK');await p.goto('http://127.0.0.1:'+port+'/admin/login?ui=classic');await p.locator('input[type=email]').fill('admin@'+domain);await p.locator('input[type=password]').fill(process.env.QA_PASSWORD);await p.locator('[data-testid=login-submit]').click();await p.waitForTimeout(800);await p.goto('http://127.0.0.1:'+port+'/admin/products?ui=classic');await p.waitForSelector('h1');console.log(domain,'ADMIN',await p.locator('h1').textContent());await p.screenshot({path:'outputs/'+(port===4181?'dracula-design-office':'dracula-food')+'/preview-admin.png',fullPage:true});await p.goto('http://127.0.0.1:'+port+'/en/');await p.waitForSelector('.hero');const d=await p.request.get('http://127.0.0.1:'+port+'/api/dracula/bootstrap?lang=en').then(r=>r.json());if(d.products.length!==expected)throw new Error('catalog mismatch');console.log(domain,d.brand.name,d.legal.address,d.products.length,'products');await p.locator('[data-action=cookies]').click();await p.screenshot({path:'outputs/'+(port===4181?'dracula-design-office':'dracula-food')+'/preview-desktop.png',fullPage:true});await p.setViewportSize({width:390,height:844});await p.screenshot({path:'outputs/'+(port===4181?'dracula-design-office':'dracula-food')+'/preview-mobile.png',fullPage:true});console.log('MOBILE',await p.evaluate(()=>[innerWidth,document.documentElement.scrollWidth]));await ctx.close();}console.log('ERRORS',errors);await browser.close();})();
